  const model=m.selected?.covered_s>0?m.selected:{},phase=s.phase||[],soc=a.battery_soc,modelSOC=model.soc_pct,flowLabel=d.active?'PRÁVĚ NAVRŽENO':'MIMO OKNO · VÝSTUP 0',currentState=REASONS[s.reason]||'Čekám na koordinátor';
