  const phaseRows=phaseFields.map(([label,value])=>'<tr><th>'+label+'</th>'+[1,2,3].map(n=>{const r=phase.find(p=>p.phase===n);return '<td>'+(r?value(r):'—')+'</td>';}).join('')+'</tr>').join('');
  const comparisonModels=d.active?m:(hist[0]?.models||{}),comparisonStatus=d.active?d.comparison_status:hist[0]?.comparison_status;
